// Lấy văn bản chứa danh sách Task từ Gemini
let rawText = $input.first().json.content.parts[0].text;

// Làm sạch ký tự rác nếu có
rawText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

const tasks = JSON.parse(rawText);
const projectId = $("Webhook").item.json.body.project_id || "a0000001-0000-0000-0000-000000000001";

// Chuyển mảng task thành từng item cho n8n
return tasks.map(task => ({
  json: {
    project_id: projectId,
    title: task.title,
    description: task.description,
    story_points: task.story_points || 3,
    required_skills: task.required_skills || [],
    priority: task.priority || "MEDIUM"
  }
}));
